import os
import subprocess

# Check all layer directories systematically
layers_dir = '/var/lib/docker/overlay2'
wal_found = False

if os.path.isdir(layers_dir):
    for layer in sorted(os.listdir(layers_dir)):
        layer_diff = os.path.join(layers_dir, layer, 'diff')
        if os.path.isdir(layer_diff):
            app_dir = os.path.join(layer_diff, 'app')
            if os.path.isdir(app_dir):
                contents = os.listdir(app_dir)
                if contents:
                    print(f"Layer {layer[:8]}: {contents}")
                    for item in contents:
                        full_path = os.path.join(app_dir, item)
                        if os.path.isfile(full_path):
                            size = os.path.getsize(full_path)
                            print(f"  - {item}: {size} bytes")
                            if 'wal' in item.lower() and not wal_found:
                                print(f"  *** FOUND WAL FILE! ***")
                                try:
                                    with open(full_path, 'rb') as f:
                                        wal_data = f.read()
                                    with open('/app/main.db-wal', 'wb') as f:
                                        f.write(wal_data)
                                    print(f"  Copied {len(wal_data)} bytes to /app/main.db-wal")
                                    wal_found = True
                                except Exception as e:
                                    print(f"  Error copying: {e}")

if not wal_found:
    print("WAL file not found in any layer")
ENDPYTHON
